static ChunkHashes sha256ChunksSequential(Path path, long size, int chunkBytes, int workers) throws IOException {
    if (size < 0 || chunkBytes < 1 || workers < 1) throw new IllegalArgumentException("invalid chunk hashing limits");
    int chunkCount = Math.max(1, Math.toIntExact((size + chunkBytes - 1) / chunkBytes));
    int workerCount = Math.min(workers, chunkCount);
    var available = new ArrayBlockingQueue<byte[]>(workerCount);
    for (int index = 0; index < workerCount; index++) available.add(new byte[chunkBytes]);
    var inFlight = new AtomicInteger();
    var maxInFlight = new AtomicInteger();
    var futures = new ArrayList<CompletableFuture<String>>(chunkCount);
    try (var executor = Executors.newFixedThreadPool(workerCount)) {
        try (FileChannel channel = FileChannel.open(path, StandardOpenOption.READ)) {
            long position = 0;
            for (int index = 0; index < chunkCount; index++) {
                int length = Math.toIntExact(Math.min(chunkBytes, size - position));
                byte[] bytes = take(available);
                readFully(channel, bytes, position, length);
                position += length;
                int active = inFlight.incrementAndGet();
                maxInFlight.accumulateAndGet(active, Math::max);
                futures.add(CompletableFuture.supplyAsync(() -> {
                    try {
                        MessageDigest digest = digest();
                        digest.update(bytes, 0, length);
                        return HexFormat.of().formatHex(digest.digest());
                    } finally {
                        inFlight.decrementAndGet();
                        available.add(bytes);
                    }
                }, executor));
            }
            var hashes = new ArrayList<String>(chunkCount);
            for (var future : futures) hashes.add(await(future));
            return new ChunkHashes(hashes, workerCount, maxInFlight.get(), position);
        }
    }
}

private static void readFully(FileChannel channel, byte[] bytes, long position, int length) throws IOException {
    ByteBuffer buffer = ByteBuffer.wrap(bytes, 0, length);
    while (buffer.hasRemaining()) {
        int read = channel.read(buffer, position + buffer.position());
        if (read < 0) throw new IOException("artifact chunk ended early");
    }
}

private static byte[] take(ArrayBlockingQueue<byte[]> available) throws IOException {
    try {
        return available.take();
    } catch (InterruptedException failure) {
        Thread.currentThread().interrupt();
        throw new IOException("artifact hashing interrupted", failure);
    }
}

private static String await(CompletableFuture<String> future) throws IOException {
    try {
        return future.get();
    } catch (InterruptedException failure) {
        Thread.currentThread().interrupt();
        throw new IOException("artifact hashing interrupted", failure);
    } catch (ExecutionException failure) {
        Throwable cause = failure.getCause();
        if (cause instanceof RuntimeException runtime) throw runtime;
        throw new IOException("artifact hashing failed", cause);
    }
}

